from collections import deque, defaultdict
R,C=len(grid),len(grid[0]); seen=set(); comps=[]
for r in range(9,R):
 for c in range(C):
  v=grid[r][c]
  if v!=1 and (r,c) not in seen:
   q=[(r,c)];seen.add((r,c));pts=[]
   while q:
    x,y=q.pop();pts.append((x,y))
    for dx,dy in [(1,0),(-1,0),(0,1),(0,-1)]:
     p=(x+dx,y+dy)
     if 9<=p[0]<R and 0<=p[1]<C and p not in seen and grid[p[0]][p[1]]==v:
      seen.add(p);q.append(p)
   comps.append((v,pts))
for v,pts in comps:
 rr=[p[0] for p in pts];cc=[p[1] for p in pts]
 print(v,len(pts),(min(rr),max(rr),min(cc),max(cc)), sorted((r-min(rr),c-min(cc)) for r,c in pts))

# connected components based on all non-bg=1 pixels across bottom
seen=set(); objs=[]
for r in range(9,R):
 for c in range(C):
  if grid[r][c]!=1 and (r,c) not in seen:
   st=[(r,c)];seen.add((r,c));pts=[]
   while st:
    x,y=st.pop();pts.append((x,y))
    for dx,dy in [(1,0),(-1,0),(0,1),(0,-1)]:
     p=(x+dx,y+dy)
     if 9<=p[0]<R and 0<=p[1]<C and p not in seen and grid[p[0]][p[1]]!=1:
      seen.add(p);st.append(p)
   objs.append(pts)
for pts in objs:
 rr=[p[0] for p in pts];cc=[p[1] for p in pts]; r0,c0=min(rr),min(cc)
 mask={(r-r0,c-c0):grid[r][c] for r,c in pts}
 print(len(pts),(r0,max(rr),c0,max(cc)), (max(rr)-r0+1,max(cc)-c0+1),[''.join(str(mask.get((i,j),'.')) for j in range(max(cc)-c0+1)) for i in range(max(rr)-r0+1)])

# create normalized object pixel patterns, values and coords
patterns=[]
for pts in objs:
 r0=min(r for r,c in pts); c0=min(c for r,c in pts)
 patt={(r-r0,c-c0):grid[r][c] for r,c in pts}
 patterns.append(patt)
# for each shape template, candidate origin translation placements whose coords subset fg
candidates=[]
for oid,p in enumerate(patterns):
 h=max(r for r,c in p)+1; w=max(c for r,c in p)+1
 cands=[]
 for r0 in range(8-h+1):
  for c0 in range(20-w+1):
   cells={(r0+r,c0+c) for r,c in p}
   if cells<=fg: cands.append((r0,c0,cells))
 candidates.append(cands)
print([len(x) for x in candidates])

bycell=defaultdict(list)
for oid,cands in enumerate(candidates):
 for r0,c0,cells in cands:
  for cell in cells: bycell[cell].append((oid,r0,c0,cells))
allmask=frozenset(fg); sols=[]; nodes=0

def search(covered, used, placements):
 global nodes
 nodes+=1
 if covered==allmask:
  if len(used)==len(patterns): sols.append(placements.copy()); return True
  return False
 # select uncovered cell with minimal available candidates
 best=None; bestopts=None
 for cell in allmask-covered:
  opts=[]
  for oid,r0,c0,cells in bycell[cell]:
   if oid not in used and not (cells & covered): opts.append((oid,r0,c0,cells))
  if not opts:return False
  if bestopts is None or len(opts)<len(bestopts):
   best,bestopts=cell,opts
   if len(opts)==1: break
 for opt in bestopts:
  oid,r0,c0,cells=opt
  if search(covered|cells, used|{oid}, placements+[(oid,r0,c0)]): return True
 return False
ok=search(frozenset(),frozenset(),[])
print(ok,nodes,len(sols),sols[:1])
